-- Original practice instructions. Idempotent append, retaining quizzes and previous material.
with authored(lesson_no,section) as (values
  (0, $curriculum${"heading": "Pierwsza zmiana w arkuszu", "text": "Kliknij komórkę C2 w warsztacie. Pole fx pokazuje jej zawartość. Wpisz 4,5 i zatwierdź Enterem. E2 przeliczy się z 700 na 1575, bo ilość została pomnożona przez cenę 350. Następnie kliknij E2 i porównaj zapis =C2*D2 w pasku formuły z wynikiem w siatce. W prawdziwym Excelu pasek formuły i pole nazwy też pomagają odróżnić adres, formułę i wynik."}$curriculum$::jsonb),
  (1, $curriculum${"heading": "Gdzie w Excelu znaleźć narzędzie", "text": "Karta Narzędzia główne (Home) służy do edycji i formatowania. W grupie Edycja znajdziesz Wypełnij i Autosumowanie. Karta Formuły (Formulas) zawiera bibliotekę funkcji i narzędzia sprawdzania formuł. Wstawianie (Insert) służy między innymi do tabel i wykresów, a Dane (Data) do sortowania i filtrowania. W warsztacie przełącz z Narzędzi głównych na Formuły i włącz Pokaż formuły, by zobaczyć zapis w siatce."}$curriculum$::jsonb),
  (2, $curriculum${"heading": "Pole nazwy i wybór zakresu", "text": "A1 to kolumna A i wiersz 1. Dwukropek łączy przeciwległe końce zakresu. E2:E4 obejmuje trzy komórki w jednej kolumnie, a C2:E4 obejmuje dziewięć komórek w prostokącie. Wpisz oba zakresy w pole adresu i obserwuj zaznaczenie. W desktopowym Excelu Ctrl+G otwiera Przejdź do, gdzie możesz podać adres. W warsztacie skrót przenosi kursor do ćwiczebnego pola adresu."}$curriculum$::jsonb),
  (3, $curriculum${"heading": "Liczba, tekst i jednostka", "text": "W kolumnie Ilość wpisuj same liczby. Jednostkę umieść w nagłówku, np. Ilość (m²). Zapis „4 m²” w komórce może zostać potraktowany jako tekst, więc mnożenie przez cenę jednostkową zgłosi błąd. Wpisz w C2 kolejno 4,5 i 4 m². Porównaj wyniki w E2. Cena za jednostkę i podana ilość powinny dotyczyć tej samej jednostki."}$curriculum$::jsonb),
  (4, $curriculum${"heading": "F2, Enter i cofanie edycji", "text": "F2 w desktopowym Excelu pozwala poprawić zawartość aktywnej komórki. W warsztacie wybierz D2 i użyj Edytuj · F2, by przejść do pola fx. Zmień tylko cenę i zatwierdź Enterem. Zobacz, co zmieniło się w podsumowaniu. Ctrl+Z cofa ostatnią zmianę. Gdy zaznaczysz komórkę i od razu zaczniesz pisać nową liczbę w Excelu, przygotowujesz zastąpienie starej zawartości. Do drobnej poprawki przydaje się F2."}$curriculum$::jsonb),
  (5, $curriculum${"heading": "Mnożenie, nawiasy i kontrola wyniku", "text": "Znakiem = rozpoczynasz formułę. Gwiazdka oznacza mnożenie, ukośnik dzielenie. Dla 2 sztuk po 350 zł formuła =C2*D2 zwróci 700. Jeśli doliczasz 23% do kwoty z E2, wpis =E2*(1+0,23) daje 861. W polskim ustawieniu arkusza przecinek może oznaczać część dziesiętną. Sprawdź sens wyniku na kartce: cena po doliczeniu dodatku powinna wzrosnąć o 161."}$curriculum$::jsonb),
  (6, $curriculum${"heading": "Autosumowanie i poprawny zakres", "text": "Zaznacz E5 i wybierz Narzędzia główne → Edycja → Autosumowanie albo Alt+= w desktopowym Excelu na Windows. Sprawdź wskazany zakres przed zatwierdzeniem. Przy kwotach 700, 360 i 150 w E2:E4 suma wyniesie 1210. Gdy zakres obejmie komórkę zawierającą własną sumę, pojawi się odwołanie cykliczne. Dla pustych pól i opisów w zakresie SUMA wykorzystuje wartości liczbowe z komórek."}$curriculum$::jsonb),
  (7, $curriculum${"heading": "Procent jako sposób prezentacji", "text": "Wpisz 0,23 do pustej komórki i użyj Format %. Zobaczysz 23%, a formuła korzystająca z tej komórki nadal będzie mnożyła przez 0,23. Gdy wpiszesz 23 i dopiero wybierzesz format procentowy, otrzymasz 2300%. Narzędzia główne → Liczba zawierają typowe formaty. Najpierw sprawdzaj wartość w pasku fx, a później sposób jej wyświetlania."}$curriculum$::jsonb),
  (10, $curriculum${"heading": "Skróty zależą od miejsca pracy", "text": "Ctrl+Home przenosi na początek arkusza, a Ctrl+End w desktopowym Excelu do ostatniej użytej komórki w ostatnim użytym wierszu i kolumnie. Ctrl+strzałka skacze do granicy obszaru danych w danym kierunku. Zachowanie zależy od pustych pól po drodze. W warsztacie po wybraniu komórki strzałki zmieniają zaznaczenie, a Shift+strzałka je rozszerza. Przycisk Zaznacz zakres pozwala zrobić to samo dotykiem."}$curriculum$::jsonb),
  (11, $curriculum${"heading": "Skopiuj formułę i sprawdź jej nowy adres", "text": "W E2 wpisz =C2*D2. Wybierz komórkę E2, skopiuj ją Ctrl+C, wybierz E3 i wklej Ctrl+V. Otrzymasz =C3*D3. Jeżeli skopiujesz ten sam zapis do E4, powinny pojawić się adresy C4 i D4. Porównuj formułę w fx po wklejeniu. Gdy potrzebujesz jedynie wyniku, w desktopowym Excelu użyj Wklej specjalnie → Wartości, żeby wynik pozostał liczbą po zmianie danych źródłowych."}$curriculum$::jsonb),
  (14, $curriculum${"heading": "Wypełnij w dół i w prawo", "text": "Wpisz =C2*D2 w E2, zaznacz E2:E4 i użyj Ctrl+D lub Narzędzia główne → Edycja → Wypełnij → W dół. Excel bierze zawartość z górnego wiersza zaznaczenia, a adresy względne przesuwa. Przed wypełnieniem upewnij się, które dane zastąpisz. W C5 wpisz =C2, zaznacz C5:E5 i użyj Ctrl+R, aby zobaczyć adresy C2, D2 i E2 w kolejnych komórkach. W warsztacie po próbie możesz przywrócić podsumowanie przyciskiem Cofnij."}$curriculum$::jsonb),
  (17, $curriculum${"heading": "Dane do wykresu, które da się sprawdzić", "text": "Przygotuj parę kolumn: nazwa usługi i koszt. W desktopowym Excelu zaznacz pozycje z nagłówkami i wybierz Wstawianie → Wykresy. Wykres kolumnowy pozwala porównać malowanie, materiały i transport, jeśli wszystkie wartości mają tę samą jednostkę. Wiersz Razem wyłącz z tego porównania, bo zawiera sumę tych samych wydatków. Sprawdź etykiety, jednostkę osi i kolejność słupków po zmianie danych."}$curriculum$::jsonb),
  (22, $curriculum${"heading": "Cztery rodzaje adresów i klawisz F4", "text": "C2 może zmienić kolumnę i wiersz po kopiowaniu. $C$2 blokuje oba, C$2 blokuje wiersz 2, a $C2 blokuje kolumnę C. W trybie edycji formuły ustaw kursor w adresie i użyj F4 w desktopowym Excelu na Windows. W warsztacie użyj też przycisku Blokuj adres. W E2 wpisz =$C$2*D2 i wypełnij do E4. C2 ma pozostać stałe, a D2 ma przejść na D3 i D4. Otwórz pasek fx po każdym kroku."}$curriculum$::jsonb),
  (28, $curriculum${"heading": "Odbiór arkusza na trzech komórkach", "text": "Skontroluj pierwszą, środkową i ostatnią formułę po wypełnieniu zakresu. Zmień jedną ilość i sprawdź, czy zmieniły się powiązane koszty oraz suma. Spróbuj też wpisać zero i tekst w polu liczbowym, a po próbie przywróć dane. Ustal, czy zero jest realną ilością, czy komunikatem o braku pomiaru. W opisie raportu zapisz, które pola odbiorca ma uzupełniać i w jakich jednostkach."}$curriculum$::jsonb)
)
update public.ta_lessons lesson
set material=jsonb_set(lesson.material,'{sections}',
    coalesce(lesson.material->'sections','[]'::jsonb)||jsonb_build_array(authored.section),true),
    updated_at=now()
from authored
where lesson.course_slug='excel-skroty' and lesson.lesson_no=authored.lesson_no
and not exists (
  select 1 from jsonb_array_elements(coalesce(lesson.material->'sections','[]'::jsonb)) as existing(section)
  where existing.section->>'heading'=authored.section->>'heading'
)
returning lesson.lesson_no,authored.section->>'heading' as added_section;
